1	/* ===== Trò chuyện theo khoảng cách (D-041): lõi phía khách (không DOM, không three) =====
2	   Sổ tin của phiên (tin mình chờ hồi âm, tin người khác, chưa đọc, giới hạn tần suất) và danh sách người ở gần có trễ hai ngưỡng.
3	   Mọi con số truyền vào từ multiParams.chat; phần DOM (chat.ts) chỉ vẽ theo những gì ở đây trả ra. */
4	import type { ChatWhy, Kind } from './protocol';
5	
6	/* pending: chờ chatAck; ok: đã tới n ≥ 1 người; alone: không ai ở gần (n = 0); fail: quá hạn / mất kết nối / không giữ chỗ / rỗng; rate: gửi quá nhanh; bad: có từ tục */
7	export type ChState = 'pending' | 'ok' | 'alone' | 'fail' | 'rate' | 'bad';
8	// key: số thứ tự duy nhất trong phiên (khóa DOM); id: số ghép chatAck (chỉ tin mình, tin người khác 0); tin mình: k 'fly', slot −1, name '' (bên vẽ dựa vào mine); at: giờ thêm (ms)
9	export interface ChMsg { key: number; id: number; mine: boolean; k: Kind; slot: number; name: string; text: string; at: number; state: ChState; n: number }
10	// Người khác cùng phòng: vị trí nội suy (m)
11	export interface ChPeer { k: Kind; slot: number; name: string; x: number; y: number; z: number }
12	
13	/* Khóa một người: loại + slot (ba nhóm slot riêng nên cùng slot khác loại là hai người) */
14	export const chKey = (k: Kind, slot: number): string => k + ':' + slot;
15	
16	/* Người ở gần (trễ hai ngưỡng): vào khi d ≤ nearIn, đã có trong prev thì ở lại tới d ≤ radius; khoảng cách 3D từ vị trí mình vừa gửi; giữ thứ tự peers */
17	export function chNear(self: { x: number; y: number; z: number } | null, peers: ChPeer[], prev: ReadonlySet<string>, nearIn: number, radius: number): ChPeer[] {
18	  if (!self) return [];
19	  const out: ChPeer[] = [];
20	  for (const p of peers) {
21	    const dx = p.x - self.x, dy = p.y - self.y, dz = p.z - self.z;
22	    const d = Math.sqrt(dx * dx + dy * dy + dz * dz);
23	    if (d <= nearIn || (d <= radius && prev.has(chKey(p.k, p.slot)))) out.push(p);
24	  }
25	  return out;
26	}
27	
28	/* ===== Sổ tin của một phiên (chỉ trong bộ nhớ; phiên mới thì clear) ===== */
29	export class ChLog {
30	  readonly list: ChMsg[] = [];
31	  unread = 0;
32	  private nextKey = 1;    // không đặt lại khi clear: khóa DOM không lặp
33	  private nextId = 1;
34	  private sent: number[] = [];   // giờ các tin mình đã gửi trong rateWinMs gần nhất (cùng cách tính với máy chủ)
35	
36	  constructor(private historyMax: number, private ackMs: number, private ratePerWin: number, private rateWinMs: number) {}
37	
38	  /* Hạn mức phía khách: < ratePerWin tin trong cửa sổ trượt rateWinMs (máy chủ cũng chặn, đây chỉ để khỏi gửi tin chắc chắn bị từ chối) */
39	  canSend(now: number): boolean {
40	    this.sent = this.sent.filter(t => now - t < this.rateWinMs);
41	    return this.sent.length < this.ratePerWin;
42	  }
43	
44	  /* rateLimited: canSend vừa trả false, tin chỉ hiện với trạng thái rate, không gửi và không ghi giờ (máy chủ cũng không ghi tin bị từ chối vì quá nhanh) */
45	  addMine(text: string, now: number, rateLimited = false): ChMsg {
46	    const m: ChMsg = { key: this.nextKey++, id: this.nextId++, mine: true, k: 'fly', slot: -1, name: '', text, at: now, state: rateLimited ? 'rate' : 'pending', n: 0 };
47	    this.list.push(m);
48	    if (!rateLimited) this.sent.push(now);
49	    return m;
50	  }
51	
52	  addTheirs(k: Kind, slot: number, name: string, text: string, now: number, panelOpen: boolean): ChMsg {
53	    const m: ChMsg = { key: this.nextKey++, id: 0, mine: false, k, slot, name, text, at: now, state: 'ok', n: 0 };
54	    this.list.push(m);
55	    if (!panelOpen) this.unread++;
56	    return m;
57	  }
58	
59	  /* Hồi âm: chỉ đổi tin mình đang pending (hồi âm trễ sau khi đã fail không đổi lại); trả tin vừa đổi, null nếu không có */
60	  ack(id: number, n: number | undefined, why: ChatWhy | undefined): ChMsg | null {
61	    const m = this.list.find(x => x.mine && x.id === id && x.state === 'pending');
62	    if (!m) return null;
63	    if (typeof n === 'number' && n >= 1) { m.state = 'ok'; m.n = n; }
64	    else if (n === 0) m.state = 'alone';
65	    else m.state = why === 'rate' ? 'rate' : why === 'bad' ? 'bad' : 'fail';
66	    return m;
67	  }
68	
69	  /* Tin pending đã chờ ≥ ackMs thành fail; trả các tin vừa đổi */
70	  expire(now: number): ChMsg[] {
71	    const out: ChMsg[] = [];
72	    for (const m of this.list) if (m.state === 'pending' && now - m.at >= this.ackMs) { m.state = 'fail'; out.push(m); }
73	    return out;
74	  }
75	
76	  /* Mất kết nối: mọi tin pending thành fail */
77	  failAll(): ChMsg[] {
78	    const out: ChMsg[] = [];
79	    for (const m of this.list) if (m.state === 'pending') { m.state = 'fail'; out.push(m); }
80	    return out;
81	  }
82	
83	  /* Gỡ tin cũ nhất tới khi còn ≤ historyMax; trả tin bị gỡ (bên vẽ xóa phần tử DOM tương ứng) */
84	  trim(): ChMsg[] {
85	    return this.list.length > this.historyMax ? this.list.splice(0, this.list.length - this.historyMax) : [];
86	  }
87	
88	  read(): void { this.unread = 0; }
89	
90	  clear(): void { this.list.length = 0; this.unread = 0; this.sent = []; }
91	}
