23	const M = CONFIG.explore.multi;
24	let session: MultiSession | null = null;
25	let sentAt = -1e9;
26	let rosterKey = '';
27	let idle: ExIdle | null = null;
28	let idleTimer = 0, beatTimer = 0;   // setInterval kiểm tra rời máy + nhịp sống; chỉ chạy khi đang bay
29	let idleShown = '';                 // chữ đang hiện ở #exMpIdle ('' = ẩn): chỉ ghi DOM khi đổi
30	
31	/* ===== Rời máy: đếm bằng setInterval (tab ẩn vẫn đếm), hết hạn thì trả slot và sang chế độ xem ===== */
32	/* ?idleMs / ?idleWarnMs chỉ đọc khi có ?test (để test rút ngắn) */
33	function idleParams(): [number, number] {
34	  const q = new URLSearchParams(location.search);
35	  if (!q.has('test')) return [M.idleMs, M.idleWarnMs];
36	  const n = (k: string, d: number) => { const v = Number(q.get(k)); return q.has(k) && v > 0 ? v : d; };
37	  return [n('idleMs', M.idleMs), n('idleWarnMs', M.idleWarnMs)];
