40	function idleShow(text: string): void {
41	  const el = document.getElementById('exMpIdle');
42	  if (!el || text === idleShown) return;
43	  /* Lần đầu hiện thì đọc to một lần; các giây sau chỉ đổi chữ, không đọc lại */
44	  el.setAttribute('aria-live', idleShown === '' ? 'polite' : 'off');
45	  idleShown = text;
46	  el.textContent = text;
47	  el.hidden = text === '';
