49	
50	function idleTick(): void {
51	  if (!session || !idle || session.phase !== 'flying') return;
52	  const now = performance.now();
53	  const st = idle.tick(now);
54	  if (st === 'ok') idleShow('');
55	  else if (st === 'warn') idleShow(t('exMpIdle', { s: idle.remaining(now) }));
56	  else { idleShow(''); session.leave(); }   // leave → onChange → idleStop
57	}
58	
59	function idleStart(): void {
60	  if (idleTimer || !session) return;   // đã chạy: không mở hai đồng hồ
61	  const [a, b] = idleParams();
62	  idle = new ExIdle(a, b); idle.reset(performance.now());
63	  idleShown = '';
64	  idleTimer = window.setInterval(idleTick, M.idleTickMs);
65	  beatTimer = window.setInterval(() => session?.heartbeat(), M.heartbeatMs);
66	}
