88	  const group = (list: typeof flyers, k: 'fly' | 'walk' | 'drive') => {
89	    for (const f of list) {
90	      const row = document.createElement('div'); row.className = 'ex-mp-row' + (k === 'walk' ? ' walk' : k === 'drive' ? ' drive' : '') + (k === kind && f.slot === mine ? ' me' : '');
91	      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
92	      const nm = document.createElement('span'); nm.textContent = f.name;
93	      if (k === 'drive') { const ic = document.createElement('span'); ic.textContent = exVehIcon(f.veh); ic.setAttribute('aria-hidden', 'true'); row.append(dot, ic, nm); }   // biểu tượng tách khỏi tên (tên RTL không kéo lệch)
94	      else row.append(dot, nm);
