122	    return q.get('multi') ?? '';
123	  },
124	  get session(): MultiSession | null { return session; },
125	  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test
126	
127	  /* Mở phiên loại kind ('fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe); veh (chỉ 'drive'): 0 ô tô, 1 xe máy (chung 5 chỗ lái với ô tô).
128	     onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
129	  begin(onReady: () => void, kind: Kind = 'fly', veh = 0): boolean {
130	    const url = exMulti.url();
131	    if (!url || session) return false;
132	    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs), undefined, kind);
133	    if (kind === 'drive') s.veh = veh === 1 ? 1 : 0;
134	    if (kind === 'walk' || s.veh === 1) s.ch = stChar.get();   // nhân vật đã chọn lần trước (chung Đi dạo và xe máy); sảnh đổi thì ghi lại (lobby.ts)
