136	    exChat.attach(s);   // trò chuyện theo khoảng cách (D-041): onChat / onChatAck, đồng hồ danh sách gần
137	    s.onPos = f => exRemotes.onPos(f, performance.now());
138	    s.onWalkPos = w => stAvatars.onPos(w, performance.now());
139	    s.peersDrive = d => exDrivers.onPos(d, performance.now());
140	    s.onChange = () => {
141	      exRemotes.sync(s.flyers, s.kind === 'fly' ? s.mySlot : -1);   // slot đi dạo và slot bay là hai nhóm: số slot của mình chỉ loại trừ trong nhóm của mình
142	      if (s.walkers.length || stAvatars.mesh) { stEnsureAvatars(); stAvatars.sync(s.walkers, s.kind === 'walk' ? s.mySlot : -1); }
143	      exDrivers.sync(s.drivers, s.kind === 'drive' ? s.mySlot : -1);
144	      if (s.phase === 'solo') exLabelsClear();
