164	
165	  /* Mỗi khung (bay, đi dạo, lái xe hoặc xem): dù người khác, người đi dạo khác, xe người khác, nhãn; đang bay thì gửi vị trí sendHz lần/s (state = null: không gửi) */
166	  update(dt: number, nowMs: number, state: GliderState | null): void {
167	    if (!session) return;
168	    exRemotes.update(nowMs);
169	    if (stAvatars.mesh) stAvatars.update(nowMs);   // người đi dạo khác, kể cả khi mình bay dù
170	    exDrivers.update(nowMs, dt);   // xe người khác, kể cả khi mình bay dù hoặc đi dạo
171	    exLabelsUpdate(camera, exRemotes, nowMs, stAvatars, exDrivers);
172	    if (state && session.kind === 'fly' && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
173	      sentAt = nowMs;
174	      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000, x = r(p.x), y = r(p.y), z = r(p.z);
175	      session.sendPos(x, y, z, a(state.yaw), a(state.bank), Math.round(nowMs));
176	      exChat.setSelf(x, y, z);   // chat: khoảng cách tính từ đúng vị trí máy chủ biết
