180	  /* Mỗi khung khi đi dạo có chỗ: gửi vị trí + dáng sendHz lần/s (s = null: không gửi) */
181	  updateWalk(nowMs: number, s: StState | null): void {
182	    if (!session || !s || session.kind !== 'walk' || session.phase !== 'flying' || nowMs - sentAt < 1000 / M.sendHz) return;
183	    sentAt = nowMs;
184	    const r = (v: number) => Math.round(v * 100) / 100, a = (v: number) => Math.round(v * 1000) / 1000;
185	    const x = r(s.x), y = r(s.y), z = r(s.z);
186	    session.sendWalk(x, y, z, a(s.yaw), s.pose, Math.round(nowMs));
187	    exChat.setSelf(x, y, z);
188	  },
189	
190	  /* Mỗi khung khi lái xe có chỗ: gửi vị trí + vận tốc + góc lái sendHz lần/s (s = null: không gửi). Cả lúc đang sơ tán khỏi nhịp quay Cầu sông Hàn.
191	     st: giá trị của trường st, mặc định góc lái ô tô; xe máy truyền bkLeanToWire(độ nghiêng) */
192	  updateDrive(nowMs: number, s: DrState | null, st?: number): void {
193	    if (!session || !s || session.kind !== 'drive' || session.phase !== 'flying' || nowMs - sentAt < 1000 / M.sendHz) return;
194	    sentAt = nowMs;
195	    const r = (v: number) => Math.round(v * 100) / 100, a = (v: number) => Math.round(v * 1000) / 1000;
196	    const x = r(s.x), y = r(s.y), z = r(s.z);
197	    session.sendDrive({ x, y, z, yaw: a(s.yaw), v: r(s.v), st: a(st ?? s.steer), ts: Math.round(nowMs) });
198	    exChat.setSelf(x, y, z);
199	  },
200	
201	  /* Người chơi vừa bấm phím điều khiển: đếm lại thời gian rời máy */
202	  activity(): void {
203	    if (!idle) return;
204	    idle.activity(performance.now());
205	    idleShow('');
206	  },
207	
