214	  watchWalker(): { x: number; y: number; z: number; yaw: number; pose: number } | null {
215	    return session && session.kind === 'walk' && session.phase === 'watching' && session.watched >= 0 ? stAvatars.slotState(session.watched) : null;
216	  },
217	
218	  /* Trạng thái xe đang xem (hết chỗ lái); null nếu không xem ai hoặc xe chưa có mẫu */
219	  watchDriver(): { x: number; y: number; z: number; yaw: number; v: number } | null {
220	    return session && session.kind === 'drive' && session.phase === 'watching' && session.watched >= 0 ? exDrivers.slotState(session.watched) : null;
221	  }
222	};
