10	
11	const KINDS: readonly unknown[] = ['fly', 'walk', 'drive'];
12	const fin = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
13	
14	export class MultiSession {
15	  phase: Phase = 'connecting';
16	  flyers: Flyer[] = [];
17	  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
18	  drivers: Flyer[] = [];   // người lái xe (lobby.drivers); máy chủ cũ không gửi
