22	  notice: Notice = '';
23	  name = '';
24	  ch = 0;             // nhân vật mình chọn (0 nam, 1 nữ); gửi kèm join kind 'walk' và join xe máy (sảnh và lời mời đều qua join())
25	  veh = 0;            // loại xe của phiên 'drive': 0 ô tô (gói join như khách cũ), 1 xe máy (join kèm veh + ch; máy chủ phải vọng veh trong joined)
26	  onChange: () => void = () => {};
27	  onPos: (f: number[][]) => void = () => {};
28	  onWalkPos: (w: number[][]) => void = () => {};
29	  peersDrive: (d: number[][]) => void = () => {};   // nhóm d của gói pos (mẫu onWalkPos): mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]
30	  chatOk = false;     // D-041: lobby gần nhất có chat === 1 (máy chủ cũ không có ⇒ ẩn chat); mất kết nối / máy chủ cũ ⇒ false
31	  onChat: (m: { k: Kind; slot: number; name: string; text: string }) => void = () => {};   // tin người khác ở gần; không gọi onChange
32	  onChatAck: (m: { id: number; n?: number; why?: ChatWhy }) => void = () => {};   // hồi âm tin mình; không gọi onChange
33	  private t: Transport | null = null;
34	  private disposed = false;
35	  private first = true; // chưa nhận lobby nào
36	
37	  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n), readonly kind: Kind = 'fly') {}
38	
39	  /* Danh sách cùng loại với mình */
40	  get peers(): Flyer[] { return this.kind === 'walk' ? this.walkers : this.kind === 'drive' ? this.drivers : this.flyers; }
41	
42	  /* Số chỗ của nhóm cùng loại */
43	  private get cap(): number { return this.kind === 'walk' ? multiParams.stroll.slots : this.kind === 'drive' ? multiParams.drive.slots : multiParams.slots; }
44	
45	  open(): void {
46	    this.connect().then(t => {
47	      if (this.disposed) { t.close(); return; }
48	      this.t = t;
49	      t.onMessage = m => this.recv(m);
50	      t.onClose = () => this.lost();
51	    }, () => {
52	      if (this.disposed) return;
53	      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
54	    });
55	  }
56	
57	  /* Người lái chỉ xin chỗ sau khi lobby đầu đã có drivers: máy chủ cũ (main trước D-034) coi join kind 'drive' là join bay và cho chiếm một chỗ bay */
58	  join(name: string): void {
59	    this.name = name; this.notice = '';
60	    if (this.kind === 'drive' && this.first) return;
61	    this.t?.send(this.kind === 'fly' ? { t: 'join', name } : this.kind === 'walk' ? { t: 'join', name, kind: 'walk', ch: this.ch }
62	      : this.veh === 1 ? { t: 'join', name, kind: 'drive', ch: this.ch, veh: 1 } : { t: 'join', name, kind: this.kind });
63	  }
64	
65	  // Rời chỗ (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
66	  leave(): void {
67	    if (this.phase !== 'flying') return;
68	    this.t?.send({ t: 'leave' });
69	    this.notice = 'released'; this.toWatching();
70	    this.onChange();
71	  }
72	
73	  // ts: giờ gửi (ms, đồng hồ của khách này) để người xem đặt mẫu theo trục giờ người gửi
74	  sendPos(x: number, y: number, z: number, yaw: number, bank: number, ts: number): void {
75	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank, ts });
76	  }
77	
78	  // Người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh) thay cho bank
79	  sendWalk(x: number, y: number, z: number, yaw: number, pose: number, ts: number): void {
80	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, pose, ts });
81	  }
82	
83	  // Người lái: v tốc độ có dấu (m/s), st góc lái (rad) thay cho bank / pose; ts giờ gửi (ms, đồng hồ khách này), không truyền thì lấy performance.now()
84	  sendDrive(p: { x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }): void {
85	    if (this.phase !== 'flying') return;
86	    const ts = typeof p.ts === 'number' ? p.ts : Math.round(performance.now());
87	    this.t?.send({ t: 'pos', x: p.x, y: p.y, z: p.z, yaw: p.yaw, v: p.v, st: p.st, ts });
88	  }
89	
90	  /* Chat: chỉ khi đang giữ chỗ, còn kết nối và máy chủ biết chat; true nếu đã đưa cho transport (chưa chắc tới máy chủ, chờ chatAck) */
91	  sendChat(text: string, id: number): boolean {
92	    if (this.phase !== 'flying' || !this.t || !this.chatOk) return false;
93	    this.t.send({ t: 'chat', text, id });
94	    return true;
95	  }
96	
97	  heartbeat(): void {
98	    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
99	  }
100	
101	  dispose(): void {
102	    this.disposed = true;
103	    this.t?.close(); this.t = null;
104	  }
105	
106	  private toWatching(): void {
107	    this.phase = 'watching'; this.mySlot = -1;
108	    if (this.kind === 'walk') this.walkers = this.walkers.filter(f => f.slot !== this.mySlotWas);
109	    else if (this.kind === 'drive') this.drivers = this.drivers.filter(f => f.slot !== this.mySlotWas);
110	    else this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
111	    this.fixWatched();
112	  }
113	  private mySlotWas = -1;
114	
115	  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác (cùng loại)
116	  private fixWatched(): void {
117	    const ids = this.peers.map(f => f.slot);
118	    if (this.phase === 'watching') {
119	      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
120	      this.invite = ids.length < this.cap;
121	    } else { this.watched = -1; this.invite = false; }
122	  }
123	
124	  private lost(): void {
125	    if (this.disposed) return;
126	    this.phase = 'solo'; this.notice = 'lost'; this.chatOk = false;
127	    this.flyers = []; this.walkers = []; this.drivers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
128	    this.t = null; this.onChange();
129	  }
130	
131	  /* Máy chủ cũ (lobby đầu không có walkers / drivers, hoặc joined xe máy không vọng veh) không biết chỗ đi dạo / lái xe / xe máy: đóng kết nối, đi / lái một mình như khi không kết nối được */
132	  private offline(): void {
133	    const t = this.t;
134	    this.t = null;
135	    if (t) { t.onClose = () => {}; t.onMessage = () => {}; t.close(); }
136	    this.phase = 'solo'; this.notice = 'offline'; this.chatOk = false;
137	    this.flyers = []; this.walkers = []; this.drivers = [];
138	    this.onChange();
139	  }
140	
141	  private recv(m: ServerMsg): void {
142	    if (this.disposed) return;
143	    switch (m.t) {
144	      case 'lobby':
145	        if (this.first && this.kind === 'walk' && !Array.isArray(m.walkers)) { this.first = false; this.offline(); return; }
146	        if (this.first && this.kind === 'drive' && !Array.isArray(m.drivers)) { this.first = false; this.offline(); return; }
147	        this.flyers = m.flyers;
148	        this.chatOk = m.chat === 1;
149	        this.walkers = Array.isArray(m.walkers) ? m.walkers : [];
150	        this.drivers = Array.isArray(m.drivers) ? m.drivers : [];
151	        if (this.first) {
152	          this.first = false;
153	          if (this.peers.length >= this.cap) this.phase = 'watching';
154	          else this.phase = 'lobby';
155	        }
156	        // đang giữ chỗ: danh sách chỉ để hiển thị
157	        this.fixWatched();
158	        break;
159	      case 'joined':
160	        /* Xe máy: máy chủ cũ (trước D-040) không vọng veh và coi mình là ô tô (khách khác thấy một chiếc ô tô): trả chỗ rồi lái một mình như máy chủ không hiểu lái xe */
161	        if (this.kind === 'drive' && this.veh === 1 && typeof m.veh !== 'number') { this.t?.send({ t: 'leave' }); this.offline(); return; }
162	        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
163	        this.fixWatched();
164	        break;
165	      case 'rejected':
166	        if (m.why === 'name') this.notice = 'nameBad';
167	        else {
168	          this.notice = 'late';   // giành trước khi đang xem, hoặc ngay ở sảnh (chỗ cuối vừa có người lúc bấm): đều báo lý do
169	          this.phase = 'watching';
170	          this.fixWatched();
171	        }
172	        break;
173	      case 'pos':
174	        this.onPos(m.f);
175	        if (Array.isArray(m.w)) this.onWalkPos(m.w);
176	        if (Array.isArray(m.d)) this.peersDrive(m.d);
177	        return;
178	      case 'released':
179	        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
180	        break;
181	      /* Chat (D-041): kiểm kiểu từng trường rồi gọi móc, không gọi onChange; gói sai kiểu bỏ lặng */
182	      case 'chat':
183	        if (KINDS.includes(m.k) && fin(m.slot) && typeof m.name === 'string' && typeof m.text === 'string') this.onChat({ k: m.k, slot: m.slot, name: m.name, text: m.text });
184	        return;
185	      case 'chatAck':
186	        if (fin(m.id) && (m.n === undefined || fin(m.n)) && (m.why === undefined || typeof m.why === 'string')) this.onChatAck({ id: m.id, n: m.n, why: m.why });
187	        return;
188	    }
189	    this.onChange();
190	  }
191	}
