1	/* ===== Dù lượn, đi dạo và lái xe nhiều người: nhãn tên nổi cạnh người chơi khác =====
2	   Một div cho mỗi slot bay, mỗi slot đi dạo và mỗi slot lái xe trong #exMpLabels (theo thứ tự đó). Dù: điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù);
3	   người đi dạo: cao hơn chân CONFIG.stroll.labelAbove m (trên đầu); xe: trên nóc, cao hơn mặt đường car.height + drive.remote.labelAbove m (xe máy: bike.body.height + bike.remote.labelAbove, trên mũ người lái). Ẩn khi sau camera hoặc slot chưa hiện; nhân vật của mình không có nhãn.
4	   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018).
5	   Bong bóng chat (D-041): exLabelsSay tạo lười một div.ex-mp-bubble cho nhãn của người gửi, hiện chat.bubbleMs ngay trên nhãn (cùng phép chiếu, dời cùng lúc nhãn dời);
6	   nhãn không có bong bóng chỉ tốn một phép so số mỗi khung. Chữ ghi bằng textContent. */
7	import * as THREE from 'three';
8	import { CONFIG } from '../../config';
9	import type { exRemotes } from './remote';
10	import type { stAvatars } from '../stroll/avatars';
11	import type { exDrivers } from './remoteDrive';
12	import type { Kind } from './protocol';
13	
14	const M = CONFIG.explore.multi, NW = M.stroll.slots, ND = M.drive.slots, CAR_TOP = CONFIG.drive.car.height + CONFIG.drive.remote.labelAbove, BIKE_TOP = CONFIG.bike.body.height + CONFIG.bike.remote.labelAbove;
15	// bub: bong bóng chat (null tới lần nói đầu); bTxt: chữ đang ghi; bUntil: mốc hết hạn (ms, 0 = không có bong bóng); bShown: đang hiện
16	interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number; bub: HTMLElement | null; bTxt: string; bUntil: number; bShown: boolean }
17	let labs: Lab[] | null = null;   // M.slots nhãn dù, NW nhãn người đi dạo rồi ND nhãn xe
18	let box: HTMLElement | null = null;   // #exMpLabels: cha của nhãn và bong bóng
19	const _v = new THREE.Vector3();
20	
21	function init(): Lab[] | null {
22	  box = document.getElementById('exMpLabels');
23	  if (!box) return null;
24	  return Array.from({ length: M.slots + NW + ND }, () => {
25	    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
26	    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9, bub: null, bTxt: '', bUntil: 0, bShown: false };
27	  });
28	}
29	
30	// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
31	const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;
32	
33	/* Đặt một nhãn tại điểm (x, y, z) với tên name; trả true nếu hiện */
34	function place(L: Lab, camera: THREE.Camera, x: number, y: number, z: number, name: string, nowMs: number, w: number, h: number): boolean {
35	  _v.set(x, y, z).applyMatrix4(camera.matrixWorldInverse);
