1	/* ===== Phòng bầu trời chung: logic thuần, không phụ thuộc Cloudflare (Durable Object bọc ngoài) ===== */
2	import { multiParams as P } from '../../../src/explore/multi/params';
3	import { exSanitizeName, exCharNorm, exVehNorm, exSanitizeChat } from '../../../src/explore/multi/protocol';
4	import type { ServerMsg, Flyer, Kind, ChatWhy } from '../../../src/explore/multi/protocol';
5	import { exIsBad, exIsBadText } from './badwords';
6	
7	export type Out = { to: string | 'all'; msg: ServerMsg };
8	
9	// pos: [slot, x, y, z, yaw, bank (người đi dạo: pose), giờ gửi]; người lái: [slot, x, y, z, yaw, v, st, giờ gửi]; giờ gửi = ts của khách (khách mới) hoặc giờ máy chủ nhận (khách cũ); dirty: có vị trí mới chưa phát
10	// ch: nhân vật người đi dạo / người đi xe máy chọn (0 nam, 1 nữ), dùng ở nhóm đi dạo và chỗ lái xe máy; phát kèm walkers / drivers của lobby để mọi khách (cả người vào sau) vẽ đúng
11	// veh: loại xe của chỗ lái (0 ô tô, 1 xe máy), chỉ dùng ở nhóm lái; ô tô luôn ch 0
12	interface Slot { id: string; name: string; seen: number; pos: number[] | null; dirty: boolean; ch: number; veh: number }
13	// stamps: giờ các gói pos trong 1 s gần nhất; chat: giờ các tin chat đã qua kiểm tần suất trong rateWinMs gần nhất (kể cả tin rỗng / tục; tin bị từ chối vì quá nhanh không ghi)
14	interface Conn { stamps: number[]; chat: number[] }
15	
16	const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
17	const wrapPi = (a: number) => a - Math.round(a / (2 * Math.PI)) * 2 * Math.PI;   // góc về [−π, π]
18	
19	export class SkyRoom {
20	  private conns = new Map<string, Conn>();
21	  private slots: (Slot | null)[] = new Array(P.slots).fill(null);
22	  private walkSlots: (Slot | null)[] = new Array(P.stroll.slots).fill(null);   // nhóm chỗ đi dạo, tách khỏi nhóm bay
23	  private driveSlots: (Slot | null)[] = new Array(P.drive.slots).fill(null);   // nhóm chỗ lái xe, tách khỏi hai nhóm kia
24	  private lastBroadcast = -Infinity;
25	
26	  private lobby(): Out {
27	    const flyers: Flyer[] = [];
28	    const walkers: Flyer[] = [];
29	    const drivers: Flyer[] = [];
30	    this.slots.forEach((s, i) => { if (s) flyers.push({ slot: i, name: s.name }); });
31	    this.walkSlots.forEach((s, i) => { if (s) walkers.push({ slot: i, name: s.name, ch: s.ch }); });
32	    this.driveSlots.forEach((s, i) => { if (s) drivers.push({ slot: i, name: s.name, ch: s.ch, veh: s.veh }); });   // khách cũ bỏ qua ch / veh
33	    return { to: 'all', msg: { t: 'lobby', flyers, walkers, drivers, chat: 1 } };   // chat 1: máy chủ biết chat (D-041), khách cũ bỏ qua
34	  }
35	
36	  connect(id: string, now: number): Out[] | null {
37	    if (!this.conns.has(id) && this.conns.size >= P.maxConns) return null;
38	    this.conns.set(id, { stamps: [], chat: [] });
39	    return [{ to: id, msg: this.lobby().msg }];
40	  }
41	
42	  slotOf(id: string): number { return this.slots.findIndex(s => s !== null && s.id === id); }   // slot bay, -1 nếu không bay
43	
44	  walkSlotOf(id: string): number { return this.walkSlots.findIndex(s => s !== null && s.id === id); }   // slot đi dạo, -1 nếu không đi dạo
45	
46	  driveSlotOf(id: string): number { return this.driveSlots.findIndex(s => s !== null && s.id === id); }   // slot lái xe, -1 nếu không lái
47	
48	  chOf(id: string): number { const w = this.walkSlotOf(id); if (w >= 0) return this.walkSlots[w].ch; const d = this.driveSlotOf(id); return d < 0 ? 0 : this.driveSlots[d].ch; }   // nhân vật của người đi dạo / đi xe máy (để lưu vào attachment); 0 nếu không
49	
50	  vehOf(id: string): number { const d = this.driveSlotOf(id); return d < 0 ? 0 : this.driveSlots[d].veh; }   // loại xe của người lái (để lưu vào attachment); 0 nếu ô tô hoặc không lái
51	
52	  kindOf(id: string): Kind | null { return this.slotOf(id) >= 0 ? 'fly' : this.walkSlotOf(id) >= 0 ? 'walk' : this.driveSlotOf(id) >= 0 ? 'drive' : null; }
53	
54	  hasFlyers(): boolean { return [this.slots, this.walkSlots, this.driveSlots].some(g => g.some(s => s !== null)); }   // còn ai giữ slot (bay, đi hoặc lái): giữ alarm quét
55	
56	  private groupOf(kind: Kind | null): (Slot | null)[] { return kind === 'walk' ? this.walkSlots : kind === 'drive' ? this.driveSlots : this.slots; }
57	
58	  /* Giờ có tin cuối của người giữ slot (để lưu vào attachment); -1 nếu không giữ slot */
59	  seenOf(id: string): number {
60	    const i = this.slotOf(id);
61	    if (i >= 0) return this.slots[i].seen;
62	    const w = this.walkSlotOf(id);
63	    if (w >= 0) return this.walkSlots[w].seen;
64	    const d = this.driveSlotOf(id);
65	    return d < 0 ? -1 : this.driveSlots[d].seen;
66	  }
67	
68	  /* Dựng lại sau hibernation. seen lấy từ attachment nếu có; không có (attachment cũ) thì coi như vừa im lặng gần hết hạn:
69	     người còn bay có một chu kỳ nhịp sống để lên tiếng, người đã chết không được gia hạn thêm mỗi lần thức dậy */
70	  restore(list: { id: string; slot: number; name: string; seen?: number; kind?: 'walk' | 'drive'; ch?: number; veh?: number }[], now: number): void {
71	    for (const e of list) {
72	      const group = this.groupOf(e.kind === 'walk' || e.kind === 'drive' ? e.kind : 'fly');
73	      if (e.slot < 0 || e.slot >= group.length) continue;
74	      if (!this.conns.has(e.id)) this.conns.set(e.id, { stamps: [], chat: [] });
75	      const seen = typeof e.seen === 'number' && Number.isFinite(e.seen) ? Math.min(e.seen, now) : now - P.slotTimeoutMs + P.heartbeatMs;
76	      const veh = e.kind === 'drive' ? exVehNorm(e.veh) : 0;   // attachment cũ không có veh: ô tô
77	      group[e.slot] = { id: e.id, name: e.name, seen, pos: null, dirty: false, ch: e.kind === 'walk' || veh === 1 ? exCharNorm(e.ch) : 0, veh };
78	    }
79	  }
80	
81	  message(id: string, raw: string, now: number): Out[] {
82	    const conn = this.conns.get(id);
83	    if (!conn || typeof raw !== 'string' || raw.length > P.chat.msgBytes) return [];
84	    let m: any;
85	    try { m = JSON.parse(raw); } catch { return []; }
86	    if (!m || typeof m !== 'object') return [];
87	    if (m.t !== 'chat' && raw.length > P.maxMsgBytes) return [];   // chỉ tin chat được dài tới chat.msgBytes; tin khác giữ maxMsgBytes như cũ
88	    const kind = this.kindOf(id);   // loại theo slot kết nối đang giữ, không theo trường trong gói
89	    const group = this.groupOf(kind);
90	    const slot = kind === null ? -1 : group.findIndex(s => s !== null && s.id === id);
91	    switch (m.t) {
92	      case 'join': return this.onJoin(id, kind !== null, m.name, m.kind === 'walk' || m.kind === 'drive' ? m.kind : 'fly', m.ch, m.veh, now);
93	      case 'leave': return this.release(id) ? [this.lobby()] : [];
94	      case 'hb': if (slot < 0) return []; group[slot].seen = now; return this.flush(now);
95	      case 'pos': return slot >= 0 ? this.onPos(conn, group[slot]!, slot, kind, m, now) : [];
96	      case 'chat': return this.onChat(id, conn, slot >= 0 ? group[slot] : null, slot, kind, m, now);
97	      default: return [];
98	    }
99	  }
100	
101	  // kind 'fly': tin trả lời không có trường kind (khách cũ hiểu được); 'walk' / 'drive' kèm kind; joined của 'drive' luôn vọng veh (khách xe máy dựa vào đó biết máy chủ hiểu xe máy)
102	  private onJoin(id: string, holding: boolean, rawName: unknown, kind: Kind, rawCh: unknown, rawVeh: unknown, now: number): Out[] {
103	    if (holding) return [];
104	    const k = kind === 'fly' ? {} : { kind };
105	    const name = typeof rawName === 'string' ? exSanitizeName(rawName) : null;
106	    if (name === null || exIsBad(name)) return [{ to: id, msg: { t: 'rejected', why: 'name', ...k } }];
107	    const group = this.groupOf(kind);
108	    const free = group.findIndex(s => s === null);
109	    if (free < 0) return [{ to: id, msg: { t: 'rejected', why: 'full', ...k } }];
110	    const veh = kind === 'drive' ? exVehNorm(rawVeh) : 0;   // khách cũ không gửi veh: ô tô
111	    group[free] = { id, name, seen: now, pos: null, dirty: false, ch: kind === 'walk' || veh === 1 ? exCharNorm(rawCh) : 0, veh };   // khách cũ không gửi ch: nam (đúng nhân vật họ tự thấy)
112	    return [{ to: id, msg: kind === 'drive' ? { t: 'joined', slot: free, kind, veh } : { t: 'joined', slot: free, ...k } }, this.lobby()];
113	  }
114	
115	  private onPos(conn: Conn, s: Slot, slot: number, kind: Kind, m: any, now: number): Out[] {
116	    const { x, y, z, yaw, ts } = m;
117	    const walk = kind === 'walk', drive = kind === 'drive';
118	    const tilt = drive ? m.v : walk ? m.pose : m.bank;   // người lái gửi v + st, người đi dạo gửi pose, người bay gửi bank; trường của loại khác bị bỏ qua
119	    const st = drive ? m.st : 0;
120	    for (const v of [x, y, z, yaw, tilt, st]) if (typeof v !== 'number' || !Number.isFinite(v)) return [];
121	    conn.stamps = conn.stamps.filter(t => now - t < 1000);
122	    if (conn.stamps.length >= P.posMaxPerSec) return [];
123	    conn.stamps.push(now);
124	    s.seen = now;
125	    const stamp = typeof ts === 'number' && Math.abs(ts) <= Number.MAX_SAFE_INTEGER ? ts : now;   // ts ngoài ±2^53 (kể cả NaN/∞) coi như không gửi, tránh đẩy độ lệch giờ của khách thành ∞
126	    if (drive) {
127	      const D = P.drive, B = D.bounds;
128	      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, D.yMin, D.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(tilt, -D.vMax, D.vMax), clamp(st, -D.steerMax, D.steerMax), stamp];
129	    } else if (walk) {
130	      const B = P.stroll.bounds;
131	      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, P.stroll.yMin, P.stroll.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(Math.round(tilt), 0, P.stroll.poseMax), stamp];
132	    } else {
133	      s.pos = [slot, clamp(x, P.bounds.x0, P.bounds.x1), clamp(y, P.floor, P.ceiling), clamp(z, P.bounds.z0, P.bounds.z1), wrapPi(yaw), clamp(tilt, -P.bankMax, P.bankMax), stamp];
134	    }
135	    s.dirty = true;
136	    return this.flush(now);
137	  }
138	
139	  /* Chat (D-041): kiểm theo thứ tự giữ chỗ → tần suất → rỗng → từ tục; qua hết thì gửi riêng tới từng người giữ chỗ (mọi nhóm) đã có pos, còn sống, cách người gửi ≤ chat.radius (3D).
140	     k / slot / name lấy từ slot của kết nối, trường cùng tên trong gói bị bỏ qua. Người gửi chưa có pos thì không ai nhận. Hồi âm chatAck { id, n } hoặc { id, why } chỉ tới người gửi */
141	  private onChat(id: string, conn: Conn, s: Slot | null, slot: number, kind: Kind | null, m: any, now: number): Out[] {
142	    const C = P.chat;
143	    const cid = Number.isSafeInteger(m.id) ? m.id : 0;
144	    const no = (why: ChatWhy): Out[] => [{ to: id, msg: { t: 'chatAck', id: cid, why } }];
145	    if (!s) return no('slot');
146	    conn.chat = conn.chat.filter(t => now - t < C.rateWinMs);
147	    if (conn.chat.length >= C.ratePerWin) return no('rate');   // tin bị từ chối vì quá nhanh không ghi giờ: gửi dồn không kéo dài thời gian khóa
148	    conn.chat.push(now);
149	    const text = exSanitizeChat(m.text);
150	    if (text === null) return no('empty');
151	    if (exIsBadText(text)) return no('bad');
152	    s.seen = now;   // chat tính là còn sống như hb
153	    const out: Out[] = [];
154	    const p = s.pos;
155	    if (p) for (const group of [this.slots, this.walkSlots, this.driveSlots]) for (const t of group) {
156	      if (!t || t.id === id || !t.pos || now - t.seen > P.slotTimeoutMs) continue;
