/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
export function setupBike(c: SwingController, onExit: () => void): void {
  ctrl = c; exit = onExit;
  window.addEventListener('keydown', (e) => {
    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (isField(e.target)) return;
    if (!BK_KEYS.has(e.code)) return;
    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
    bkKeys.add(e.code);
    if (e.repeat) return;
    /* phím một lần (không theo giữ): về làn, xi nhan, góc nhìn */
    if (e.code === 'KeyR') bkRecover(state!, net!);
    else if (e.code === 'KeyQ') bkSignal(state!, 1);
    else if (e.code === 'KeyE') bkSignal(state!, -1);
    else if (e.code === 'KeyV') bike.setView(camB.view === 3 ? 1 : 3);
  });
  window.addEventListener('keyup', (e) => {
    bkKeys.delete(e.code);
    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
  });
  const drop = drBindDrop(window, document, bkKeys);
  const hornOff = () => { hornTouch = false; bkSound.horn(false); if (hornBtn) hornBtn.classList.remove('on'); };
  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); hornOff(); } });
  window.addEventListener('blur', hornOff);
  document.addEventListener('visibilitychange', () => { if (document.hidden) hornOff(); });
  /* HUD riêng: xi nhan, góc nhìn, về làn bấm một lần (click: chuột, chạm, bàn phím); còi giữ (con trỏ riêng, nhả / hủy / mất capture là thôi) */
---
  placeAt: drPlaceAt,
  stats: drSceneStats,
  preload(): void { void drCarLoad(); }
};

