/* Một bước: cổng nhịp quay, sơ tán / chuyển động, hình xe, camera, hiệu ứng đêm */
function advance(dt: number, inp: DrInput): void {
  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
  const s = state!;
  if (!drEvacStep(s, net!, dt, ctrl ? drSwingBudget(ctrl) : undefined)) drStep(s, inp, net!, boxes, trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes), dt);
  drCars.place(selfSlot, state!);
  drCamPlace(camera, state!, camS, net!, dt);
  controls.target.set(state!.x, state!.y, state!.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
  const now = performance.now();
  exMulti.update(dt, now, null);     // xe người khác, người bay / đi dạo, nhãn tên; không làm gì khi lái một mình
  exMulti.updateDrive(now, state);   // gửi vị trí + vận tốc + góc lái khi đang giữ chỗ (kể cả lúc sơ tán)
  drHudUpdate(state!, exDrivers.dots()); drSound.update(state!.v);
/* Một bước: cổng nhịp quay, chuyển động, nhân vật, camera, hiệu ứng đêm, người chơi khác */
function advance(dt: number, inp: StInput): void {
  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
  stStep(state!, inp, map!, dt);
  stAvatars.setSelf(selfSlot, state, dt);   // dt cho mixer của nhân vật có xương
  stCamPlace(camera, controls.target, state!, camS, map!, dt);
  exNightStep(dt, false);
  const now = performance.now();
  exMulti.update(dt, now, null);   // người khác (đi dạo + bay), nhãn tên; không làm gì khi đi một mình
  exMulti.updateWalk(now, state);  // gửi vị trí + dáng khi đang giữ chỗ
  bkFx.update(s, shared.uNight.value, dry ? 0 : weatherU.uRain.value, dt, s.pitch, dry ? 0 : weatherU.uWet.value);
  riderStep(s, dt);
  riderEye();
  bkCamStep(camB, s, dt, motionK);
  if (bkCamPlace(camera, s, camB, n, dt)) onResize();   // fov / near đổi trong lúc trộn góc nhìn
  rider?.setFirstPerson(bkCamHideHead(camB));   // cùng giá trị trộn đã làm mượt mà camera dùng
  if (dash) { dash.bind(model!.dashMat); dash.update(dt, s.v, s.rpm, s.sig); }
  controls.target.set(s.x, s.y, s.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
  const now = performance.now();
  exMulti.update(dt, now, null);                        // xe người khác, người bay / đi dạo, nhãn tên; không làm gì khi lái một mình
  exMulti.updateDrive(now, s, bkLeanToWire(s.lean));    // gửi vị trí + vận tốc + độ nghiêng (qua trường st) khi đang giữ chỗ

